import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useParams } from 'react-router-dom';
import { products } from '../../mocks/products';
import { useCart } from '../../context/CartContext';
import ResponsiveImage from '../../components/ResponsiveImage';
import { commonShadow } from '../../utils/uiEffects';

export default function ProductDetail() {
  const { productId } = useParams();
  const product = products.find(p => p.id === productId);
  const [quantity, setQuantity] = useState(1);
  const [selectedSize, setSelectedSize] = useState('regular');
  const [showAddedToast, setShowAddedToast] = useState(false);
  const { addToCart } = useCart();

  if (!product) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-[#0A0604] via-[#140B07] to-[#25160F] flex items-center justify-center">
        <div className="text-center">
          <i className="ri-error-warning-line text-6xl text-[#C5A021] mb-4"></i>
          <h2 className="font-syncopate text-2xl text-[#F8F4F0] mb-2">Product Not Found</h2>
          <button
            onClick={() => window.REACT_APP_NAVIGATE('/menu')}
            className="mt-4 px-6 py-3 bg-[#C5A021] text-[#140B07] font-outfit rounded-full cursor-pointer whitespace-nowrap"
          >
            Back to Menu
          </button>
        </div>
      </div>
    );
  }

  const sizes = [
    { id: 'regular', name: 'Regular', price: product.price },
    { id: 'large', name: 'Large', price: Math.round(product.price * 1.3) },
    { id: 'jumbo', name: 'Jumbo', price: Math.round(product.price * 1.6) }
  ];

  const handleAddToCart = () => {
    // Add item to cart using context
    addToCart({
      id: product.id,
      name: product.name,
      price: currentPrice,
      size: selectedSize,
      quantity: quantity,
      image: product.image
    });

    // Show toast
    setShowAddedToast(true);
    setTimeout(() => setShowAddedToast(false), 2000);
  };

  const handleBackClick = () => {
    if (window.history.length > 1) {
      window.history.back();
    } else if (window.REACT_APP_NAVIGATE) {
      window.REACT_APP_NAVIGATE('/menu');
    }
  };

  const currentPrice = sizes.find(s => s.id === selectedSize)?.price || product.price;
  const totalPrice = currentPrice * quantity;

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#0A0604] via-[#140B07] to-[#25160F] pt-32 pb-20">
      <div className="max-w-7xl mx-auto px-8">
        {/* Back Button */}
        <motion.button
          onClick={handleBackClick}
          className="mb-8 flex items-center gap-2 text-[#F8F4F0]/70 hover:text-[#C5A021] transition-colors cursor-pointer font-outfit whitespace-nowrap"
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          whileHover={{ x: -5 }}
        >
          <i className="ri-arrow-left-line text-xl"></i>
          Back to Menu
        </motion.button>

        <div className="grid lg:grid-cols-2 gap-12">
          {/* Product Image */}
          <motion.div
            className="relative"
            initial={{ opacity: 0, x: -50 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.6 }}
          >
            <div className="relative w-full h-[600px] rounded-3xl overflow-hidden glass-panel border border-[#C5A021]/20">
              {/* Veg Tag */}
              <div className="absolute top-6 left-6 z-10 w-8 h-8 border-2 border-green-500 rounded flex items-center justify-center bg-[#140B07]/80 backdrop-blur-sm">
                <div className="w-4 h-4 rounded-full bg-green-500"></div>
              </div>

              {/* Best Seller Tag */}
              {product.isBestSeller && (
                <div className="absolute top-6 right-6 z-10 px-4 py-2 bg-[#C5A021] rounded-full">
                  <span className="font-outfit text-sm font-bold text-[#140B07] whitespace-nowrap">
                    ⭐ BEST SELLER
                  </span>
                </div>
              )}

              <div className="w-full h-full">
                <ResponsiveImage
                  src={product.image}
                  alt={product.name}
                  className="w-full h-full object-cover object-top"
                  sizes="(max-width: 1024px) 100vw, 50vw"
                />
              </div>
            </div>
          </motion.div>

          {/* Product Details */}
          <motion.div
            initial={{ opacity: 0, x: 50 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.6 }}
          >
            <div className="glass-panel rounded-3xl p-8 border border-[#C5A021]/20">
              <h1 className="font-syncopate text-4xl text-[#F8F4F0] mb-4">
                {product.name}
              </h1>

              <div className="flex items-center gap-4 mb-6">
                <div className="flex items-center gap-1">
                  <i className="ri-star-fill text-yellow-400 text-lg"></i>
                  <span className="font-outfit text-lg text-[#F8F4F0] font-semibold">
                    {product.rating}
                  </span>
                  <span className="font-outfit text-sm text-[#F8F4F0]/60">
                    ({product.reviews} reviews)
                  </span>
                </div>
                <span className="px-3 py-1 bg-[#C5A021]/20 border border-[#C5A021] rounded-full text-xs font-outfit text-[#C5A021] whitespace-nowrap">
                  {product.category}
                </span>
              </div>

              <p className="font-outfit text-lg text-[#F8F4F0]/80 leading-relaxed mb-8">
                {product.description}
              </p>

              {/* Size Selection */}
              <div className="mb-8">
                <h3 className="font-syncopate text-sm text-[#F8F4F0] mb-4">SELECT SIZE</h3>
                <div className="grid grid-cols-3 gap-3">
                  {sizes.map((size) => (
                    <motion.button
                      key={size.id}
                      onClick={() => setSelectedSize(size.id)}
                      className={`py-4 rounded-xl font-outfit text-sm cursor-pointer whitespace-nowrap transition-all ${selectedSize === size.id
                        ? 'bg-gradient-to-r from-[#C5A021] to-[#D4AF37] text-[#140B07] font-bold border-2 border-[#C5A021]'
                        : 'bg-[#25160F]/50 text-[#F8F4F0]/70 border border-[#C5A021]/20 hover:border-[#C5A021]/50'
                        }`}
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                    >
                      <div>{size.name}</div>
                      <div className="text-xs mt-1">₹{size.price}</div>
                    </motion.button>
                  ))}
                </div>
              </div>

              {/* Quantity Selector */}
              <div className="mb-8">
                <h3 className="font-syncopate text-sm text-[#F8F4F0] mb-4">QUANTITY</h3>
                <div className="flex items-center gap-4">
                  <motion.button
                    onClick={() => setQuantity(Math.max(1, quantity - 1))}
                    className="w-12 h-12 rounded-full bg-[#25160F]/50 border border-[#C5A021]/20 flex items-center justify-center cursor-pointer hover:border-[#C5A021] transition-colors"
                    whileHover={{ scale: 1.1 }}
                    whileTap={{ scale: 0.9 }}
                  >
                    <i className="ri-subtract-line text-[#C5A021] text-xl"></i>
                  </motion.button>
                  <span className="font-syncopate text-2xl text-[#F8F4F0] w-16 text-center">
                    {quantity}
                  </span>
                  <motion.button
                    onClick={() => setQuantity(quantity + 1)}
                    className="w-12 h-12 rounded-full bg-[#25160F]/50 border border-[#C5A021]/20 flex items-center justify-center cursor-pointer hover:border-[#C5A021] transition-colors"
                    whileHover={{ scale: 1.1 }}
                    whileTap={{ scale: 0.9 }}
                  >
                    <i className="ri-add-line text-[#C5A021] text-xl"></i>
                  </motion.button>
                </div>
              </div>

              {/* Price & Add to Cart */}
              <div className="border-t border-[#C5A021]/20 pt-6">
                <div className="flex items-center justify-between mb-6">
                  <div>
                    <div className="font-outfit text-sm text-[#F8F4F0]/60 mb-1">Total Price</div>
                    <div className="font-syncopate text-3xl text-[#C5A021] font-bold">
                      ₹{totalPrice}
                    </div>
                  </div>
                </div>

                <motion.button
                  onClick={handleAddToCart}
                  className={`w-full py-5 bg-gradient-to-r from-[#C5A021] to-[#D4AF37] text-[#140B07] font-syncopate font-bold text-sm tracking-wider rounded-full cursor-pointer whitespace-nowrap relative overflow-hidden ${commonShadow}`}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                >
                  <i className="ri-shopping-cart-line mr-2"></i>
                  ADD TO CART
                </motion.button>
              </div>
            </div>
          </motion.div>
        </div>
      </div>

      {/* Added to Cart Toast */}
      <AnimatePresence>
        {showAddedToast && (
          <motion.div
            className="fixed bottom-8 right-8 z-50 glass-panel-strong rounded-2xl p-6 border-2 border-[#C5A021]"
            initial={{ opacity: 0, y: 50, scale: 0.8 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 50, scale: 0.8 }}
          >
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-full bg-[#C5A021] flex items-center justify-center">
                <i className="ri-check-line text-2xl text-[#140B07]"></i>
              </div>
              <div>
                <h4 className="font-syncopate text-sm text-[#F8F4F0] mb-1">Added to Cart!</h4>
                <p className="font-outfit text-xs text-[#F8F4F0]/60">{product.name}</p>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
